using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.SGR.PerfilMenuBotones;using GraphApi.Services.SGR.PerfilMenuBotones;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.SGR.PerfilMenuBotones{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de PerfilMenuBotones: creación, actualización y eliminación.")]    public class PerfilMenuBotonesMutation    {        [Authorize]        [GraphQLName("createPerfilMenuBotones")]        [GraphQLDescription("Crea un nuevo PerfilMenuBotone usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadPerfilMenuBotones> CreatePerfilMenuBotonesAsync(            [GraphQLDescription("Datos necesarios para crear el PerfilMenuBotone.")]            clCreatePerfilMenuBotones objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de PerfilMenuBotone.")]            IPerfilMenuBotonesService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreatePerfilMenuBotones(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updatePerfilMenuBotones")]        [GraphQLDescription("Actualiza los campos especificados de un PerfilMenuBotone existente.")]        public async Task<clReadPerfilMenuBotones?> UpdatePerfilMenuBotonesAsync(            [GraphQLDescription("Datos del PerfilMenuBotone a actualizar.")]            clUpdatePerfilMenuBotones objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de PerfilMenuBotone.")]            IPerfilMenuBotonesService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdatePerfilMenuBotones(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deletePerfilMenuBotones")]        [GraphQLDescription("Elimina un PerfilMenuBotone por su ID.")]        public async Task<bool> delPerfilMenuBotonesAsync(            [GraphQLDescription("ID del PerfilMenuBotone a eliminar.")]            int nPerfilMenuBotonesID,            [Service]            [GraphQLDescription("Servicio para operaciones de PerfilMenuBotone.")]            IPerfilMenuBotonesService objService        )        {            return await objService.DeletePerfilMenuBotones(nPerfilMenuBotonesID);        }    }}